+  enabled: boolean;
+  onChange: () => void;
+  disabled?: boolean;
+}
+
+function ToggleSwitch({ enabled, onChange, disabled }: ToggleSwitchProps) {
+  return (
+    <button
+      type="button"
+      role="switch"
+      aria-checked={enabled}
+      disabled={disabled}
+      onClick={onChange}
+      className={cn(
